def q(prompt,correct,wrong,explain,evidence):
 return dict(prompt=prompt,choices=[correct,*wrong],answer=0,explain=explain,evidence=evidence)
def r(id,level,title,ja,uk,targets,questions):
 return dict(id=id,level=level,title=title,ja=ja,uk=uk,targets=targets,questions=questions)
